<?php
namespace Modules\Academy\Controllers\Web;
use Core\http\ResponseFactory;use Modules\Academy\Services\ZarinpalPaymentService;use Modules\Academy\Services\OfflineInstallmentPaymentService;use RuntimeException;
class ZarinpalPaymentController{public function __construct(private ZarinpalPaymentService$s,private OfflineInstallmentPaymentService$offline){}public function start(int$invoiceId,int$installmentId){try{return ResponseFactory::json(['success'=>true,'data'=>$this->s->start((int)auth()->id(),$invoiceId,$installmentId)]);}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}public function offline(int$invoiceId,int$installmentId){try{$raw=base64_decode(strtr((string)request()->input('payload_b64',''),'-_','+/'),true);$data=$raw===false?[]:(json_decode($raw,true)?:[]);return ResponseFactory::json(['success'=>true,'data'=>$this->offline->record((int)auth()->id(),$invoiceId,$installmentId,$data)]);}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}public function callback(){try{$token=(string)($_GET['token']??'');$authority=(string)($_GET['Authority']??'');if(!preg_match('/^[a-f0-9]{64}$/',$token)||$authority==='')throw new RuntimeException('پارامترهای بازگشت پرداخت معتبر نیست.');$r=$this->s->callback($token,$authority,(string)($_GET['Status']??''));$query=http_build_query(['payment'=>$r['success']?'success':'failed','ref'=>$r['referenceId']??'']);return redirect('/analytics/admin-panel?'.$query.'#finance');}catch(\Throwable$e){return redirect('/analytics/admin-panel?'.http_build_query(['payment'=>'failed','message'=>$e->getMessage()]).'#finance');}}}
